/// Operations Activity Component Schema.
#[derive(Debug, Default, Clone, PartialEq, EnergymlObject)]
#[energyml(
    package = "witsml",
    version = "2.0",
    xml_name = "DrillActivity"
)]
pub struct DrillActivity {
    /// Date and time that activities started.
    #[energyml(elem, xml_name = "DTimStart", pattern = ".+T.+[Z+\\-].*")]
    pub d_tim_start: Option<String>,

    /// Date and time that activities ended.
    #[energyml(elem, xml_name = "DTimEnd", pattern = ".+T.+[Z+\\-].*")]
    pub d_tim_end: Option<String>,

    /// The activity duration (commonly in hours).
    #[energyml(elem, xml_name = "Duration")]
    pub duration: Option<energyml_eml_2_1::TimeMeasure>,

    /// The measured depth to the drilling activity/operation.
    #[energyml(elem, xml_name = "Md")]
    pub md: Option<MeasuredDepthCoord>,

    /// True vertical depth to the drilling activity/operation.
    #[energyml(elem, xml_name = "Tvd")]
    pub tvd: Option<WellVerticalDepthCoord>,

    /// Phase refers to a large activity classification, e.g., drill surface hole.
    #[energyml(elem, xml_name = "Phase", max_length = 64)]
    pub phase: Option<String>,

    /// A code used to define rig activity.
    #[energyml(elem, xml_name = "ActivityCode")]
    pub activity_code: Option<DrillActivityCode>,

    /// Custom string to further define an activity.
    #[energyml(elem, xml_name = "DetailActivity", max_length = 64)]
    pub detail_activity: Option<String>,

    /// Classifier (planned, unplanned, downtime).
    #[energyml(elem, xml_name = "TypeActivityClass")]
    pub type_activity_class: Option<DrillActivityClassType>,

    /// Measured depth interval over which the activity was conducted.
    #[energyml(elem, xml_name = "ActivityMdInterval")]
    pub activity_md_interval: Option<energyml_eml_2_1::MdInterval>,

    /// True vertical depth interval over which the activity was conducted.
    #[energyml(elem, xml_name = "ActivityTvdInterval")]
    pub activity_tvd_interval: Option<energyml_eml_2_1::TvdInterval>,

    /// Range of bit measured depths over which the activity occurred.
    #[energyml(elem, xml_name = "BitMdInterval")]
    pub bit_md_interval: Option<energyml_eml_2_1::MdInterval>,

    /// Finish, interrupted, failed, etc.
    #[energyml(elem, xml_name = "State", max_length = 64)]
    pub state: Option<String>,

    /// The outcome of the detailed activity.
    #[energyml(elem, xml_name = "StateDetailActivity")]
    pub state_detail_activity: Option<StateDetailActivity>,

    /// Operator company name.
    #[energyml(elem, xml_name = "Operator", max_length = 64)]
    pub operator: Option<String>,

    /// A pointer to the tubular object  related to this activity.
    #[energyml(elem, xml_name = "Tubular", max_length = 64)]
    pub tubular: Option<String>,

    /// Is the activity optimum.? Values are "true" (or "1") and "false" (or "0").
    #[energyml(elem, xml_name = "Optimum")]
    pub optimum: Option<bool>,

    /// Does activity bring closer to objective?  Values are "true" (or "1") and "false" (or "0").
    #[energyml(elem, xml_name = "Productive")]
    pub productive: Option<bool>,

    /// The item state for the data object.
    #[energyml(elem, xml_name = "ItemState")]
    pub item_state: Option<ItemState>,

    /// Comments and remarks.
    #[energyml(elem, xml_name = "Comments", max_length = 2000)]
    pub comments: Option<String>,

    /// Extensions to the schema based on a name-value construct.
    #[energyml(elem, xml_name = "ExtensionNameValue")]
    pub extension_name_value: Vec<energyml_eml_2_1::ExtensionNameValue>,

    #[energyml(elem, xml_name = "ProprietaryCode")]
    pub proprietary_code: Vec<energyml_eml_2_1::ObjectAlias>,

    /// Unique identifier for this instance of DrillActivity.
    #[energyml(attr, xml_name = "uid", max_length = 64)]
    pub uid: String,

}

/// Used to capture a daily drilling report focused on reporting from the operator to partners or to a governmental agency. For a similar report whose focus is service company to operator, see the OpsReport object.
